CREATE FUNCTION public.prune_risk_history(retain_days integer DEFAULT 90) RETURNS bigint
    LANGUAGE sql
    AS $$
            WITH pruned AS (
                UPDATE risk_assessments
                SET factors = '{}'::jsonb
                WHERE NOT is_current
                  AND computed_at < now() - make_interval(days => retain_days)
                  AND factors <> '{}'::jsonb
                RETURNING 1
            )
            SELECT count(*) FROM pruned;
        $$;


