--
-- Name: v_current_risk; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_current_risk AS
 SELECT f.id AS finding_id,
    f.status,
    f.package_name,
    f.installed_version,
    f.fixed_version,
    f.package_type,
    f.first_seen,
    a.id AS asset_id,
    a.hostname,
    a.environment,
    a.internet_facing,
    a.business_criticality,
    a.owner_team,
    a.owner_email,
    c.cve_id,
    c.cvss_v31_score,
    c.cvss_severity,
    c.epss_score,
    c.kev_listed,
    c.kev_ransomware,
    ra.risk_score,
    ra.risk_band,
    ra.sla_days,
    ra.due_date,
    ra.factors,
    ra.policy_version,
    ra.computed_at,
    (ra.due_date < CURRENT_DATE) AS overdue,
    (ra.due_date - CURRENT_DATE) AS days_remaining
   FROM (((public.risk_assessments ra
     JOIN public.findings f ON ((f.id = ra.finding_id)))
     JOIN public.assets a ON ((a.id = f.asset_id)))
     JOIN public.cves c ON ((c.cve_id = f.cve_id)))
  WHERE ra.is_current;


